ALTER TABLE organisations MODIFY code VARCHAR(50) NULL, MODIFY type VARCHAR(64) NOT NULL, ADD type_id BIGINT UNSIGNED NULL, ADD state_id BIGINT UNSIGNED NULL, ADD address TEXT NULL, ADD email VARCHAR(190) NULL, ADD phone VARCHAR(30) NULL, ADD FOREIGN KEY(type_id) REFERENCES master_data(id), ADD FOREIGN KEY(state_id) REFERENCES master_data(id);
